export const todaySceneKeys = ["5-2", "5-3", "5-4", "5-5", "5-6", "5-37-2", "5-39", "5-41", "5-42", "8-42"];

/** Вызывной 10.07 ↔ либретто 24.08 (номера сцен уехали). */
export const sceneAlias: Record<string, string[]> = {
  "5-2": ["5-2"],
  "5-3": ["5-3"],
  "5-4": ["5-4"],
  "5-5": ["5-5"],
  "5-6": ["5-6"],
  "5-37-2": ["5-42"],
  "5-39": ["5-44"],
  "5-41": ["5-46"],
  "5-42": ["5-47"],
  "8-42": ["8-51"],
};

export function keysOf(scene: string) {
  return sceneAlias[scene] ?? [scene];
}

export function sceneHit(scenes: string, key: string) {
  return scenes.split(/[,;]/).some((raw) => {
    const n = raw.trim().split(/\s/)[0];
    return n === key || n.startsWith(`${key}-`) || n.startsWith(`${key}/`);
  });
}

export function isTodayObject(o: ShootObject) {
  const blob = `${o.name} ${o.sub}`.toLowerCase();
  if (/кладбищ|патанин|потанин|слюдян/.test(blob)) return true;
  return todaySceneKeys.some((k) => keysOf(k).some((a) => sceneHit(o.scenes, a)));
}

export function objectsForScene(scene: string) {
  return objects.filter((o) => keysOf(scene).some((k) => sceneHit(o.scenes, k)));
}
